L15_1 = "\235\130\160 \236\131\129\235\140\128\235\161\156 \235\184\148\235\159\172\237\149\145\236\157\132 \236\147\176\235\139\164\235\139\136 \235\132\136\235\143\132 \236\149\136 \235\179\184 \236\130\172\236\157\180 \235\167\142\236\157\180 \235\139\179\236\149\132\235\185\160\236\161\140\234\181\172\235\130\152. \237\149\156 \235\176\169 \235\168\185\236\151\136\236\150\180."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "\231\167\129\227\130\146\231\155\184\230\137\139\227\129\171\227\131\150\227\131\169\227\131\149\227\130\163\227\131\179\227\130\176\227\130\146\228\189\191\227\129\134\227\129\170\227\130\147\227\129\166\227\128\129\232\166\139\227\129\170\227\129\132\233\150\147\227\129\171\227\129\130\227\130\147\227\129\159\227\130\130\227\129\154\227\129\132\227\129\182\227\130\147\n\227\130\132\227\130\138\230\137\139\227\129\171\227\129\170\227\129\163\227\129\159\227\129\152\227\130\131\227\129\170\227\129\132\227\128\130\228\184\128\230\137\139\233\163\159\227\130\137\227\129\163\227\129\161\227\130\131\227\129\163\227\129\159\227\130\143\227\128\130"
L14_1.m_Talk_JPN = L15_1
L15_1 = "You got me. I never thought you\226\128\153d bluff against me."
L14_1.m_Talk_ENG = L15_1
L15_1 = "\231\171\159\231\132\182\230\149\162\229\146\140\230\136\145\231\142\169\232\138\177\230\139\155\239\188\140\233\128\153\233\186\188\228\185\133\228\184\141\232\166\139\239\188\140\228\189\160\228\185\159\232\174\138\229\190\151\229\165\184\232\169\144\228\184\141\229\176\145\229\152\155\239\188\129\232\162\171\228\189\160\230\147\186\228\186\134\228\184\128\233\129\147\239\188\129"
L14_1.m_Talk_TWN = L15_1
L15_1 = "\224\185\128\224\184\170\224\184\163\224\185\135\224\184\136\224\185\128\224\184\152\224\184\173\224\184\136\224\184\153\224\185\132\224\184\148\224\185\137 \224\185\132\224\184\161\224\185\136\224\184\153\224\184\182\224\184\129\224\184\167\224\185\136\224\184\178\224\185\128\224\184\152\224\184\173\224\184\136\224\184\176\224\184\171\224\184\165\224\184\173\224\184\129\224\184\129\224\184\177\224\184\153\224\185\129\224\184\154\224\184\154\224\184\153\224\184\181\224\185\137"
L14_1.m_Talk_THA = L15_1
L15_1 = "Tao ph\225\187\165c m\195\160y r\225\187\147i. Tao ch\198\176a bao gi\225\187\157 ngh\196\169 r\225\186\177ng m\195\160y c\195\179 c\225\187\173a \196\145\225\187\131 ph\225\186\163n l\225\186\161i tao."
L14_1.m_Talk_VTN = L15_1
L15_1 = "\231\171\159\231\132\182\232\162\171\228\189\160\230\145\134\228\186\134\228\184\128\233\129\147\239\188\140\231\156\139\230\157\165\232\191\153\228\186\155\229\185\180\230\178\161\232\167\129\239\188\140\228\189\160\228\185\159\229\173\166\228\188\154\228\186\134\229\190\136\229\164\154\232\138\177\230\139\155\229\145\162\227\128\130"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Du hast gegen mich geblufft. Du bist viel gerissener geworden, als ich dich kannte. Damit hast du mir geh\195\182rig eins ausgewischt."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Ton coup de bluff a fonctionn\195\169, on dirait. Je dois reconna\195\174tre que tu es plus rus\195\169e que la derni\195\168re fois."
L14_1.m_Talk_FRA = L15_1
