L15_1.m_fTalkTime = 0.03
L16_1 = "\227\129\167\227\130\130\227\128\129\227\129\169\227\129\134\227\129\151\227\130\136\227\129\134\239\188\159\227\128\128\228\187\138\229\155\158\227\129\174\229\175\190\229\177\128\227\129\175\231\167\129\227\129\174\229\139\157\227\129\161\227\129\191\227\129\159\227\129\132\227\130\136\239\188\159"
